"""Run records: one JSON file per tool call, enough to replay the call without an agent.A record holds the tool and its version, the arguments, the SHA-256 of every inputfile, the SHA-256 of the result, and wall-clock and processor time. Replaying a runre-executes the tool with the recorded arguments, after checking that the inputfiles are unchanged, and compares the result hash.Records live in the user's visible ``records/runs/`` (legacy cases stay in place)."""from __future__ import annotationsimport hashlibimport jsonimport platformimport sysimport timeimport uuidfrom collections.abc import Callable, Mappingfrom dataclasses import dataclass, fieldfrom datetime import UTC, datetimefrom pathlib import Pathfrom typing import Anyfrom element_surrogate import __version__from element_surrogate.file_io import publish_file, read_utf8from element_surrogate.project_paths import STATE_DIRNAME as STATE_DIRNAMEfrom element_surrogate.project_paths import state_directoryRECORD_SCHEMA = "element_surrogate.run_record.v1"_CHUNK = 1 << 20def sha256_file(path: str | Path) -> str:    """SHA-256 of a file, read in chunks so large field maps need little memory."""    digest = hashlib.sha256()    with Path(path).open("rb") as handle:        for block in iter(lambda: handle.read(_CHUNK), b""):            digest.update(block)    return digest.hexdigest()def canonical_json(value: Any) -> str:    """JSON with sorted keys and no insignificant whitespace, so equal values hash equally."""    return json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=False)def sha256_json(value: Any) -> str:    return hashlib.sha256(canonical_json(value).encode("utf-8")).hexdigest()@dataclass(frozen=True)class Tool:    """A recordable tool: a deterministic function and the arguments that name input files."""    name: str    func: Callable[..., dict[str, Any]]    version: str    input_file_args: tuple[str, ...] = ()    read_only: bool = True    def input_paths(self, arguments: Mapping[str, Any]) -> list[str]:        return [            str(arguments[name])            for name in self.input_file_args            if name in arguments and arguments[name] is not None        ]@dataclassclass ReplayReport:    run_id: str    tool: str    reproduced: bool    changed_inputs: list[str] = field(default_factory=list)    recorded_result_sha256: str = ""    replayed_result_sha256: str = ""    changed_implementation: bool = False    def as_dict(self) -> dict[str, Any]:        return {            "run_id": self.run_id,            "tool": self.tool,            "reproduced": self.reproduced,            "changed_inputs": self.changed_inputs,            "recorded_result_sha256": self.recorded_result_sha256,            "replayed_result_sha256": self.replayed_result_sha256,            "changed_implementation": self.changed_implementation,        }class RunStore:    """Reads/writes the project's single visible or legacy run-record root."""    def __init__(self, project_dir: str | Path):        self.root = state_directory(project_dir) / "runs"    def new_run_id(self) -> str:        stamp = datetime.now(UTC).strftime("%Y%m%dT%H%M%S%fZ")        return f"{stamp}-{uuid.uuid4().hex[:8]}"    def path_for(self, run_id: str) -> Path:        if not run_id or any(sep in run_id for sep in ("/", "\\", "..")):            raise ValueError(f"not a run id: {run_id!r}")        return self.root / f"{run_id}.json"    def write(self, record: Mapping[str, Any]) -> Path:        self.root.mkdir(parents=True, exist_ok=True)        path = self.path_for(record["run_id"])        tmp = path.with_suffix(".json.tmp")        tmp.write_text(json.dumps(record, indent=2, sort_keys=True) + "\n", encoding="utf-8")        publish_file(tmp, path)  # a reader never sees a half-written record        return path    def load(self, run_id: str) -> dict[str, Any]:        record: dict[str, Any] = json.loads(read_utf8(self.path_for(run_id)))        if record.get("schema") != RECORD_SCHEMA:            raise ValueError(f"run {run_id} has unsupported schema {record.get('schema')!r}")        return record    def list_runs(self) -> list[str]:        if not self.root.is_dir():            return []        return sorted(p.stem for p in self.root.glob("*.json"))def record_call(store: RunStore, tool: Tool, arguments: Mapping[str, Any]) -> dict[str, Any]:    """Run a tool, write its run record, and return its result with the run id.    A failing call is recorded too, with status ``error``, and the exception is re-raised.    """    arguments = dict(arguments)    run_id = store.new_run_id()    record: dict[str, Any] = {        "schema": RECORD_SCHEMA,        "run_id": run_id,        "tool": tool.name,        "tool_version": tool.version,        "package_version": __version__,        "arguments": arguments,        "inputs": [],        "started_utc": datetime.now(UTC).isoformat(),        "python": sys.version.split()[0],        "platform": platform.platform(),        "implementation": implementation_identity(),    }    record.update(status="running")    store.write(record)  # durable before execution, including hard process interruption    wall0, cpu0 = time.perf_counter(), time.process_time()    stage = "input_validation"    try:        record["inputs"] = [            {"path": p, "sha256": sha256_file(p)} for p in tool.input_paths(arguments)        ]        store.write(record)        stage = "tool_execution"        result = tool.func(**arguments)    except Exception as exc:        record.update(status="error", error=f"{type(exc).__name__}: {exc}", error_stage=stage)        record.update(_timing(wall0, cpu0))        store.write(record)        raise    record.update(status="ok", result=result, result_sha256=sha256_json(result))    record.update(_timing(wall0, cpu0))    store.write(record)    return {"run_id": run_id, **result}def implementation_identity() -> dict[str, str]:    """Pin small package source/knowledge files without collecting runtime arrays."""    root = Path(__file__).parent    result = {        p.relative_to(root).as_posix(): sha256_file(p)        for p in sorted(root.rglob("*"))        if p.suffix in (".py", ".md", ".json", ".yaml", ".yml", ".txt")        or p.name in ("LICENSE", "NOTICE")    }    roots = (        Path(__file__).resolve().parents[2] / "skills",        Path(__file__).resolve().parents[1] / "share/element-surrogate/skills",        Path(sys.prefix) / "share/element-surrogate/skills",    )    skill_root = next((root for root in roots if root.is_dir()), None)    if skill_root is not None:        for entry in sorted(skill_root.rglob("SKILL.md")):            result.update(                {                    "skills/" + p.relative_to(skill_root).as_posix(): sha256_file(p)                    for p in sorted(entry.parent.rglob("*"))                    if p.is_file() and p.suffix in (".md", ".yaml", ".json")                }            )    return resultdef replay(store: RunStore, registry: Mapping[str, Tool], run_id: str) -> ReplayReport:    """Re-execute a recorded call and report whether it reproduces the recorded result."""    record = store.load(run_id)    if record.get("status") != "ok":        raise ValueError(f"run {run_id} did not succeed; there is no result to reproduce")    tool = registry[record["tool"]]    if not tool.read_only:        raise ValueError(            "generic replay refuses tools with side effects; use their explicit check/resume path"        )    report = ReplayReport(        run_id=run_id,        tool=tool.name,        reproduced=False,        recorded_result_sha256=record["result_sha256"],    )    for entry in record["inputs"]:        path = Path(entry["path"])        if not path.is_file() or sha256_file(path) != entry["sha256"]:            report.changed_inputs.append(entry["path"])    if report.changed_inputs:        return report    if record.get("tool_version") != tool.version or (        "implementation" in record and record["implementation"] != implementation_identity()    ):        report.changed_implementation = True        return report    result = tool.func(**record["arguments"])    report.replayed_result_sha256 = sha256_json(result)    report.reproduced = report.replayed_result_sha256 == report.recorded_result_sha256    return reportdef _timing(wall0: float, cpu0: float) -> dict[str, float]:    return {        "wall_time_s": time.perf_counter() - wall0,        "cpu_time_s": time.process_time() - cpu0,    }